"button.primary { background:linear-gradient(135deg,var(--red),var(--rosso)); border-color:transparent; color:#fff; box-shadow:0 6px 18px #e8202a40; flex:1 1 160px; }\n"
"button:focus-visible, a:focus-visible, select:focus-visible, input:focus-visible, summary:focus-visible { outline:2px solid var(--yellow); outline-offset:3px; }\n"
".info { margin:12px 0 0; padding:10px 12px; border-radius:10px; background:#ffd21f12; border-left:3px solid var(--yellow); font-size:13px; color:#fde68a; }\n"
".info:empty { display:none; }\n"
".hint { color:var(--muted); font-size:13px; margin:8px 0 0; }\n"
".hint:empty { display:none; }\n"
".msg { color:var(--up); font-size:13px; min-height:1em; margin-top:8px; }\n"
"details.card > summary { cursor:pointer; list-style:none; display:flex; justify-content:space-between; align-items:center; font-size:13px; font-weight:700; letter-spacing:1.6px; text-transform:uppercase; color:var(--muted); }\n"
"details.card > summary::-webkit-details-marker { display:none; }\n"
"details.card > summary::after { content:\"＋\"; font-size:16px; }\n"
"details.card[open] > summary::after { content:\"−\"; }\n"
".tech { display:grid; gap:18px; margin-top:16px; }\n"
".tech h3 { margin:0 0 6px; font-size:14px; }\n"
"table { width:100%; border-collapse:collapse; font-variant-numeric:tabular-nums; }\n"
"td, th { padding:7px 4px; border-bottom:1px solid #ffffff0d; text-align:left; font-size:13px; }\n"
"th { color:var(--muted); font-weight:600; }\n"
".btns span { display:inline-block; min-width:44px; text-align:center; padding:6px 8px; margin:2px; border-radius:8px; background:var(--panel2); color:var(--muted); font-size:13px; font-weight:600; }\n"
".btns span.on { background:var(--yellow); color:#1a1405; }\n"
".bar { height:8px; background:var(--panel2); border-radius:4px; overflow:hidden; margin-top:6px; }\n"
".bar i { display:block; height:100%; background:var(--yellow); width:0; }\n"
".help { color:var(--muted); font-size:13px; margin:0; padding-left:18px; }\n"
".help li + li { margin-top:4px; }\n"
"@media (max-width:520px) {\n"
"  main { padding:0 12px 24px; }\n"
"  .topbar { flex-wrap:wrap; }\n"
"  .tilt { font-size:44px; }\n"
"  .segmented button { font-size:13px; padding:10px 4px; }\n"
"  .count b { font-size:28px; }\n"
"  .rows select { width:100%; }\n"
"  .actions button { flex:1 1 auto; }\n"
"}\n"
"</style>\n"
"</head>\n"
"<body>\n"
"<main>\n"
"  <header class=\"topbar\">\n"
"    <div class=\"brand\">\n"
"      <span class=\"brand-mark\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2.2\" stroke-linecap=\"round\"><path d=\"M6 4v16M12 4v16M18 4v8H6\"/></svg></span>\n"
"      <div><strong>Câmbio PS Move</strong><span class=\"eyebrow\">458 Spider · sequencial</span></div>\n"
"    </div>\n"
"    <div class=\"status\" id=\"status\" role=\"status\">Carregando…</div>\n"
"  </header>\n"
"  <nav class=\"nav\" aria-label=\"Páginas\"><a href=\"/\">← Ajustes do volante</a><a href=\"/overlay\">Cockpit ↗</a></nav>\n"
"\n"
"  <section class=\"card hero\" aria-label=\"Posição do câmbio\">\n"
"    <div class=\"hero-top\">\n"
"      <div class=\"tilt\"><small>Inclinação</small><span id=\"tilt\">0,0°</span></div>\n"
"      <span class=\"pill\" id=\"state\">centro</span>\n"
"    </div>\n"
"    <div>\n"
"      <div class=\"gauge\" id=\"gauge\">\n"
"        <div class=\"zone down\" id=\"zoneDown\"></div>\n"
"        <div class=\"zone up\" id=\"zoneUp\"></div>\n"
"        <div class=\"mark\" id=\"levelMark\"></div>\n"
"        <div class=\"mark\" style=\"left:50%\"></div>\n"
"        <div class=\"needle\" id=\"needle\" style=\"left:50%\"></div>\n"
"      </div>\n"
"      <div class=\"scale\"><span>◀ puxar −30°</span><span>0°</span><span>+30° empurrar ▶</span></div>\n"
"    </div>\n"
"    <div class=\"counts\">\n"
"      <div class=\"count down\"><span>▼ Desceu</span><b id=\"downs\">0</b></div>\n"
"      <div class=\"count up\"><span>▲ Subiu</span><b id=\"ups\">0</b></div>\n"
"    </div>\n"
"    <div class=\"side\" id=\"extra\"></div>\n"
"  </section>\n"
"\n"
"  <section class=\"card\">\n"
"    <h2>Usar o PS Move como</h2>\n"
"    <select id=\"use\" hidden>\n"
"      <option value=\"off\">Desligado (só mede)</option>\n"
"      <option value=\"shift\">Câmbio</option>\n"
"      <option value=\"lever\">Freio de mão</option>\n"
"    </select>\n"
"    <div class=\"segmented\" role=\"group\" aria-label=\"Usar o PS Move como\">\n"
"      <button type=\"button\" data-use=\"off\">Desligado<small>só mede</small></button>\n"
"      <button type=\"button\" data-use=\"shift\">Câmbio<small>sobe e desce</small></button>\n"
"      <button type=\"button\" data-use=\"lever\">Freio de mão<small>puxa e segura</small></button>\n"
"    </div>\n"
"    <div class=\"rows\">\n"
"      <label class=\"for-shift\"><span>Modo rápido<small>Troca no meio do movimento, sem esperar parar</small></span><span class=\"switch\"><input id=\"fast\" type=\"checkbox\"><i></i></span></label>\n"
"      <label class=\"for-shift\"><span>Subir marcha<small>Botão enviado ao empurrar</small></span><select id=\"up\" data-none=\"Borboleta direita do volante\"></select></label>\n"
"      <label class=\"for-shift\"><span>Descer marcha<small>Botão enviado ao puxar</small></span><select id=\"down\" data-none=\"Borboleta esquerda do volante\"></select></label>\n"
"      <label><span id=\"hbLabel\">Freio de mão (gatilho T)</span><select id=\"handbrake\" data-none=\"Desativado\"></select></label>\n"
"      <label class=\"for-lever\"><span>Segurar junto com o puxão<small>Evita acionar se o Move cair</small></span>\n"
"        <select id=\"leverHold\">\n"
"          <option value=\"0\">Nada (só puxar)</option><option value=\"1\">Gatilho T</option>\n"
"          <option value=\"2\">Cruz (X)</option><option value=\"3\">Círculo</option><option value=\"4\">Quadrado</option>\n"
"        </select>\n"
"      </label>\n"
"      <label class=\"for-lever\"><span>Puxar para trás a partir de<small>Ângulo que aciona o freio</small></span><span><input id=\"leverDeg\" type=\"number\" step=\"0.5\" min=\"3\" max=\"40\"> °</span></label>\n"
"    </div>\n"
"    <div class=\"actions\">\n"
"      <button id=\"saveOpts\" class=\"primary\">Salvar no PS5</button>\n"
"      <button id=\"testUp\" class=\"for-shift\">▲ Testar subir</button><button id=\"testDown\" class=\"for-shift\">▼ Testar descer</button>\n"
"    </div>\n"
"    <p class=\"info\" id=\"optsInfo\"></p>\n"
"    <p class=\"hint\" id=\"optsHelp\"></p>\n"
"  </section>\n"
"\n"
"  <details class=\"card\">\n"
"    <summary>Ajuste fino e detalhes</summary>\n"
"    <div class=\"tech\">\n"
"      <div>\n"
"        <h3>Ajustes</h3>\n"
"        <div class=\"actions\" style=\"margin-top:0;align-items:center\">\n"
"          <label>Degrau mínimo <input id=\"on\" type=\"number\" step=\"0.5\" min=\"2\" max=\"45\"> °</label>\n"
"          <input id=\"off\" type=\"hidden\">\n"
"          <button id=\"saveTh\">Aplicar</button>\n"
"        </div>\n"
"        <div class=\"actions\">\n"
"          <button id=\"centre\">Centralizar agora</button>\n"
"          <button id=\"reset\">Zerar contadores</button>\n"
"          <button id=\"export\">Exportar registro</button>\n"
"        </div>\n"
"        <div class=\"msg\" id=\"msg\" role=\"status\"></div>\n"
"      </div>\n"
"      <div>\n"
"        <h3>Posições paradas</h3>\n"
"        <p class=\"sub\">Cada ângulo onde o tubo ficou parado. Os níveis do suporte aparecem aqui.</p>\n"
"        <table><thead><tr><th>Ângulo</th><th>Vezes</th></tr></thead><tbody id=\"rests\"></tbody></table>\n"
"      </div>\n"
"      <div>\n"
"        <h3>Últimas trocas</h3>\n"
"        <table><thead><tr><th>Troca</th><th>Pico</th><th>Giro</th><th>Tempo</th><th>Há</th></tr></thead><tbody id=\"events\"></tbody></table>\n"
"      </div>\n"
"      <div>\n"
"        <h3>Botões do Move</h3>\n"
"        <div class=\"btns\" id=\"btns\"></div>\n"
"        <p class=\"sub\" style=\"margin-top:6px\">Gatilho T: <span id=\"trig\">0</span></p>\n"
"        <div class=\"bar\"><i id=\"trigBar\"></i></div>\n"
"      </div>\n"
"      <ul class=\"help\">\n"
"        <li>A troca conta quando o tubo para num nível do suporte: um nível à frente sobe, um atrás desce. A linha amarela é o nível atual.</li>\n"
"        <li>Deixe o tubo no meio e parado: o centro é marcado sozinho. Para refazer, segure o botão Move 1 s.</li>\n"
"        <li>Se empurrar mostrar ângulo negativo ou quase zero, incline o tubo para frente e segure Triângulo 1 s.</li>\n"
"        <li>Com o modo Desligado, o câmbio só mede e nada chega ao jogo.</li>\n"
"      </ul>\n"
"    </div>\n"
"  </details>\n"
"</main>\n"
"<script>\n"
"const $ = id => document.getElementById(id);\n"
"const fmt = (v, d = 1) => Number(v).toLocaleString('pt-BR', { minimumFractionDigits: d, maximumFractionDigits: d });\n"
"let last = null, editing = false, shown = null, optsEditing = false;\n"
"const RANGE = 30;\n"
"const pos = deg => 50 + Math.max(-RANGE, Math.min(RANGE, deg)) / RANGE * 50;\n"
"\n"
"function render(s) {\n"
"  last = s;\n"
"  const live = s.connected && s.age_ms < 1500;\n"
"  $('status').textContent = live ? (s.centred ? 'Move conectado' : 'Conectado · deixe o tubo parado no meio') : 'Move desconectado · aperte PS no Move';\n"
"  $('status').className = 'status ' + (live ? 'ok' : 'bad');\n"
"  /* Sensor noise is about ±0.5°: hold the needle until the change is real. */\n"
"  if (shown === null || Math.abs(s.tilt - shown) >= 0.8) shown = s.tilt;\n"
"  if (Math.abs(shown) < 2) shown = 0;\n"
"  $('needle').style.left = pos(shown) + '%';\n"
"  $('zoneUp').style.left = pos(s.level + s.on) + '%'; $('zoneUp').style.right = '0';\n"
"  $('levelMark').style.left = pos(s.level) + '%';\n"
"  $('zoneDown').style.left = '0'; $('zoneDown').style.width = pos(s.level - s.on) + '%';\n"
"  $('tilt').textContent = (shown > 0 ? '+' : '') + fmt(shown) + '°';\n"
"  const st = $('state');\n"
"  st.textContent = s.state === 1 ? 'indo para frente' : s.state === 2 ? 'indo para trás' : 'parado no nível ' + (s.level > 0 ? '+' : '') + fmt(s.level) + '°';\n"
"  st.className = 'pill' + (s.state === 1 ? ' up' : s.state === 2 ? ' down' : '');\n"
"  $('extra').textContent = 'lado ' + fmt(s.side) + '° · giro ' + fmt(s.gyro, 0) + '°/s' + (s.forward_taught ? ' · frente ensinada' : '');\n"
"  $('ups').textContent = s.ups; $('downs').textContent = s.downs;\n"
"  $('rests').innerHTML = s.rests.slice().sort((a, b) => b.deg - a.deg)\n"
"    .map(r => `<tr><td>${(r.deg > 0 ? '+' : '') + fmt(r.deg)}°</td><td>${r.hits}</td></tr>`).join('') || '<tr><td colspan=\"2\" class=\"sub\">Nenhuma ainda</td></tr>';\n"
"  $('events').innerHTML = s.events.slice(0, 12)\n"
"    .map(e => `<tr><td>${e.kind === 'up' ? '▲ subiu' : '▼ desceu'}</td><td>${fmt(e.peak)}°</td><td>${fmt(e.gyro, 0)}°/s</td><td>${e.ms} ms</td><td>${fmt(e.ago_ms / 1000)} s</td></tr>`).join('') || '<tr><td colspan=\"5\" class=\"sub\">Nenhuma ainda</td></tr>';\n"
"  const names = [['move', 'Move'], ['t', 'T'], ['cross', '✕'], ['circle', '○'], ['square', '□'], ['triangle', '△']];\n"
"  $('btns').innerHTML = names.map(([k, n]) => `<span class=\"${s[k] ? 'on' : ''}\">${n}</span>`).join('');\n"
"  $('trig').textContent = s.trigger; $('trigBar').style.width = (s.trigger / 255 * 100) + '%';\n"
"  if (!editing) { $('on').value = s.on; $('off').value = s.off; }\n"
"  if (!optsEditing) {\n"
"    $('use').value = !s.enabled ? 'off' : s.lever ? 'lever' : 'shift';\n"
"    $('fast').checked = !!s.fast;\n"
"    $('leverDeg').value = s.lever_deg;\n"
"    $('leverHold').value = String(s.lever_hold);\n"
"    ['up', 'down', 'handbrake'].forEach(k => $(k).value = String(s[k]));\n"
"    showUse();\n"
"  }\n"
"  const mode = !s.fast ? 'modo nível' : s.learned ? 'modo rápido ativo' : `modo rápido aprendendo: mude de nível ${3 - s.learn_count} vez(es) devagar`;\n"
"  $('optsInfo').textContent = !s.enabled ? 'Desligado · só medindo, nada chega ao jogo.'\n"
"    : s.lever ? (s.lever_pulled ? 'Freio de mão PUXADO' : 'Freio de mão solto') + (s.handbrake ? '' : ' · escolha o botão do freio')\n"
"    : `Câmbio · ${s.sent} trocas enviadas ao jogo · ${mode}.`;\n"
"}\n"
"\n"
"async function poll() {\n"
"  try {\n"
"    const r = await fetch('/api/shifter', { cache: 'no-store' });\n"
"    if (r.ok) render(await r.json());\n"
"  } catch (e) { $('status').textContent = 'Sem resposta do PS5'; $('status').className = 'status bad'; }\n"
"  setTimeout(poll, 100);\n"
"}\n"
"\n"
"async function post(path, data) {\n"
"  const r = await fetch(path, { method: 'POST', headers: { 'Content-Type': 'application/x-www-form-urlencoded' }, body: new URLSearchParams(data) });\n"
"  $('msg').textContent = r.ok ? 'Feito.' : 'Valor recusado.';\n"
"  return r.ok;\n"
"}\n"
"\n"
"['on', 'off'].forEach(id => { $(id).addEventListener('focus', () => editing = true); $(id).addEventListener('blur', () => editing = false); });\n"
"$('saveTh').onclick = async () => { await post('/api/shifter/thresholds', { on: $('on').value, off: $('off').value }); editing = false; };\n"
"$('centre').onclick = () => post('/api/shifter/centre', { centre: '1' });\n"
"const PAD_BUTTONS = [[16384, 'Cruz (X)'], [8192, 'Círculo'], [32768, 'Quadrado'], [4096, 'Triângulo'], [1024, 'L1'], [2048, 'R1'],\n"
"  [256, 'L2'], [512, 'R2'], [2, 'L3'], [4, 'R3'], [16, 'Cima'], [64, 'Baixo'], [128, 'Esquerda'], [32, 'Direita'], [8, 'Options'], [1048576, 'Touchpad']];\n"
"['up', 'down', 'handbrake'].forEach(id => {\n"
"  const sel = $(id);\n"
"  sel.innerHTML = `<option value=\"0\">${sel.dataset.none}</option>` + PAD_BUTTONS.map(([v, n]) => `<option value=\"${v}\">${n}</option>`).join('');\n"
"});\n"
"function showUse() {\n"
"  const use = $('use').value;\n"
"  document.querySelectorAll('[data-use]').forEach(b => b.setAttribute('aria-pressed', String(b.dataset.use === use)));\n"
"  document.querySelectorAll('.for-shift').forEach(el => el.hidden = use !== 'shift');\n"
"  document.querySelectorAll('.for-lever').forEach(el => el.hidden = use !== 'lever');\n"
"  $('hbLabel').innerHTML = use === 'lever' ? 'Botão do freio de mão<small>Segurado enquanto o tubo está puxado</small>' : 'Freio de mão<small>Enquanto aperta o gatilho T</small>';\n"
"  $('optsHelp').textContent = use === 'lever'\n"
"    ? 'Na posição normal o freio fica solto. Puxe o tubo para trás para segurar o botão; volte para a frente para soltar.'\n"
"      + ($('leverHold').value !== '0' ? ' Só aciona com o botão escolhido apertado junto.' : '')\n"
"    : use === 'shift' ? 'Escolha os mesmos botões que o jogo usa para trocar de marcha.' : '';\n"
"}\n"
"document.querySelectorAll('[data-use]').forEach(b => b.addEventListener('click', () => { $('use').value = b.dataset.use; optsEditing = true; showUse(); }));\n"
"['use', 'fast', 'up', 'down', 'handbrake', 'leverDeg', 'leverHold'].forEach(id => $(id).addEventListener('change', () => { optsEditing = true; showUse(); }));\n"
"$('testUp').onclick = () => post('/api/shifter/test', { kind: 'up' });\n"
"$('testDown').onclick = () => post('/api/shifter/test', { kind: 'down' });\n"
"$('saveOpts').onclick = async () => {\n"
"  const use = $('use').value;\n"
"  await post('/api/shifter/options', {\n"
"    enabled: use === 'off' ? '0' : '1', lever: use === 'lever' ? '1' : '0', lever_deg: $('leverDeg').value, lever_hold: $('leverHold').value,\n"
"    fast: $('fast').checked ? '1' : '0', handbrake: $('handbrake').value, up: $('up').value, down: $('down').value\n"
"  });\n"
"  optsEditing = false;\n"
"};\n"
"$('reset').onclick = () => post('/api/shifter/reset', { reset: '1' });\n"
"$('export').onclick = () => {\n"
"  if (!last) return;\n"
"  const d = new Date(), p = n => String(n).padStart(2, '0');\n"
"  const name = `cambio-move-${d.getFullYear()}${p(d.getMonth() + 1)}${p(d.getDate())}-${p(d.getHours())}${p(d.getMinutes())}.json`;\n"
"  const a = document.createElement('a');\n"
"  const shifter = { ...last, events: last.events.map(e => ({ ...e, at: new Date(d - e.ago_ms).toLocaleTimeString('pt-BR', { hour12: false }) + '.' + String((d - e.ago_ms) % 1000).padStart(3, '0') })) };\n"
"  a.href = URL.createObjectURL(new Blob([JSON.stringify({ exported: d.toISOString(), shifter }, null, 2)], { type: 'application/json' }));\n"
"  a.download = name; a.click(); URL.revokeObjectURL(a.href);\n"
"};\n"
"poll();\n"
"</script>\n"
"</body>\n"
"</html>\n";
